function validate(input) {
  const [{ Tasks = [] }] = input;
  if (Tasks.length === 0) return 'Tasks needs at least one row.';
  const ids = new Set();
  for (const [id, , day] of Tasks) {
    if (id === null) return 'Every task needs a task_id.';
    if (ids.has(id)) return `task_id ${id} appears twice in Tasks.`;
    ids.add(id);
    if (day === null) return `Task ${id} needs a submit_date.`;
  }
  return null;
}

