function generate(rand, size) {
  const pad = value => String(value).padStart(2, '0');
  const dayAt = (base, offset) => {
    const d = new Date(base + offset * 86400000);
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  };
  const Tasks = [];
  if (size === 'small') {
    // Two weeks starting on Monday 2022-06-13; some sets keep only weekends or only weekdays.
    const base = Date.UTC(2022, 5, 13);
    const mode = rand();
    const offsets = [];
    for (let i = 0; i < 14; i++) {
      const weekend = i % 7 >= 5;
      if (mode < 0.15 && !weekend) continue;
      if (mode >= 0.15 && mode < 0.3 && weekend) continue;
      offsets.push(i);
    }
    const count = 1 + Math.floor(rand() * 8);
    for (let id = 1; id <= count; id++) Tasks.push([id, 1 + Math.floor(rand() * 4), dayAt(base, offsets[Math.floor(rand() * offsets.length)])]);
  } else {
    const base = Date.UTC(2021, 0, 1);
    for (let id = 1; id <= 2000; id++) Tasks.push([id, 1 + Math.floor(rand() * 50), dayAt(base, Math.floor(rand() * 730))]);
  }
  return [{ Tasks }];
}
